parameters.jsCode:
const raw = $input.first().json;
let html = raw.output || raw.text || '';

// Clean markdown if Gemini wrapped it
html = html.replace(/^```html?\s*\n?/i, '').replace(/\n?```\s*$/i, '').trim();

// Find HTML start if there's preamble text
if (!html.startsWith('<')) {
  const idx = html.indexOf('<!');
  if (idx > -1) html = html.substring(idx);
  else if (html.indexOf('<html') > -1) html = html.substring(html.indexOf('<html'));
}

// Generate unique page ID
const pageId = 'lp-' + Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 8);

// Store in workflow static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.pages) staticData.pages = {};
staticData.pages[pageId] = {
  html: html,
  empresa: $('Recebe Dados POST').first().json.body.empresa || 'Empresa',
  createdAt: new Date().toISOString()
};

// Limit stored pages to last 50
const keys = Object.keys(staticData.pages);
if (keys.length > 50) {
  const sorted = keys.sort((a, b) => {
    const ta = staticData.pages[a].createdAt || '';
    const tb = staticData.pages[b].createdAt || '';
    return ta.localeCompare(tb);
  });
  for (let i = 0; i < sorted.length - 50; i++) {
    delete staticData.pages[sorted[i]];
  }
}

const viewUrl = 'https://n8n6.inovareinteligenciaartificial.com/webhook/landing-page-view?id=' + pageId;

return [{ json: { pageId, viewUrl, url: viewUrl, success: true } }];

const input = $input.first().json;
const pageId = input.query ? input.query.id : "";
const staticData = $getWorkflowStaticData("global");
const pages = staticData.pages || {};

if (pageId && pages[pageId]) {
  return [{ json: { html: pages[pageId].html } }];
}

const errorPage = "<" + "!DOCTYPE html><html><head><meta charset=UTF-8><title>404</title>" +
  "<style>body{font-family:system-ui;background:#07111f;color:#f4f7fb;display:flex;align-items:center;justify-content:center;min-height:100vh;text-align:center}" +
  "h1{font-size:72px;color:#7c3aed}p{color:#91a4b8;margin:16px 0}a{color:#7c3aed}</style></head>" +
  "<body><div><h1>404</h1><p>Landing page nao encontrada.</p>" +
  "<a href=/webhook/landing-page>Criar nova</a></div></body></html>";
return [{ json: { html: errorPage } }];

